// ── Utility ───────────────────────────────────────────────────────────────────
const clamp = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v));
const iclamp = (v: number, i: [number, number], o: [number, number]) =>
  clamp(interpolate(v, i, o), Math.min(o[0], o[1]), Math.max(o[0], o[1]));

// Simple seeded pseudo-random (deterministic per-path)
const seed = (n: number, s = 137) => ((n * s + 42) % 1000) / 1000;

// ── The full mark as a single SVG ────────────────────────────────────────────
// In 1080×1920 we scale to fit: viewBox 1698×1832 → at 1080 wide the scale is
// 1080/1698 ≈ 0.636, giving height ≈ 0.636 × 1832 ≈ 1164px (fits in 1920).
const MusiniqueLogo: React.FC<{
  fill?: string;
  opacity?: number;
  pathFills?: string[];
  pathOpacities?: number[];
  pathTransforms?: string[];
  style?: React.CSSProperties;
}> = ({ fill = INK, opacity = 1, pathFills, pathOpacities, pathTransforms, style }) => (
  <svg
    viewBox="0 0 1698.01 1832.98"
    width="85%"
    height="auto"
    style={{ display: 'block', ...style }}
    preserveAspectRatio="xMidYMid meet"
  >
    {MUSINIQUE_PATHS.map((d, i) => (
      <path
        key={i}
        d={d}
        fill={pathFills ? pathFills[i] : fill}
        opacity={pathOpacities ? pathOpacities[i] : opacity}
        transform={pathTransforms ? pathTransforms[i] : undefined}
      />
    ))}
  </svg>
);

// ── Technique label overlay ───────────────────────────────────────────────────
const TechLabel: React.FC<{ name: string; sub?: string; progress?: number }> = ({
  name, sub, progress = 1,
}) => {
  const o = clamp(progress, 0, 1);
  return (
    <div style={{
      position: 'absolute', top: '5%', left: 0, right: 0,
      display: 'flex', flexDirection: 'column', alignItems: 'center',
      gap: 6, pointerEvents: 'none', opacity: o,
      transform: `translateY(${(1 - o) * -12}px)`,
    }}>
      <div style={{
        fontFamily: SERIF, fontSize: 38, fontWeight: 600,
        color: INK, letterSpacing: '-0.01em', textAlign: 'center',
        padding: '0 40px',
      }}>{name}</div>
      <div style={{ width: 52, height: 3, background: SPARK, borderRadius: 2 }} />
      {sub && <div style={{
        fontFamily: SANS, fontSize: 18, color: CLAUDE.INK_SOFT,
        letterSpacing: 1, textTransform: 'uppercase' as const, marginTop: 2,
      }}>{sub}</div>}
    </div>
  );
};

// ── Accent rule (bottom-left terracotta bar) ─────────────────────────────────
const AccentRule: React.FC<{ opacity?: number }> = ({ opacity = 1 }) => (
  <div style={{
    position: 'absolute', bottom: '6%', left: '8%', width: 64, height: 3,
    background: SPARK, borderRadius: 2, opacity,
  }} />
);

// ── Logo centering wrapper ────────────────────────────────────────────────────
const LogoCenter: React.FC<{ children: React.ReactNode; style?: React.CSSProperties }> = ({ children, style }) => (
  <div style={{
    position: 'absolute', top: 0, left: 0, right: 0, bottom: 0,
    display: 'flex', alignItems: 'center', justifyContent: 'center',
    paddingTop: 120, // leave room for TechLabel
    ...style,
  }}>
    {children}
  </div>
);

