// ── B01: Spring Entrance ──────────────────────────────────────────────────────
const B01_SpringEntrance: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const labelIn = spring({ frame, fps, config: { damping: 28, stiffness: 120, mass: 0.8 } });
  const enter = spring({ frame: frame - 15, fps, config: { damping: 22, stiffness: 180, mass: 0.9 } });
  const sc = clamp(enter, 0, 1);
  return (
    <AbsoluteFill style={{ background: PAGE }}>
      <TechLabel name="Spring Entrance" sub="Default spring · whole mark" progress={labelIn} />
      <LogoCenter>
        <div style={{ transform: `scale(${sc}) translateY(${(1-sc)*80}px)`, opacity: sc }}>
          <MusiniqueLogo />
        </div>
      </LogoCenter>
      <AccentRule opacity={sc} />
    </AbsoluteFill>
  );
};

// ── B02: Overshoot Spring ─────────────────────────────────────────────────────
const B02_OvershootSpring: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const labelIn = spring({ frame, fps, config: { damping: 28, stiffness: 120, mass: 0.8 } });
  const enter = spring({ frame: frame - 15, fps, config: { damping: 4, stiffness: 400, mass: 1.5 } });
  const sc = enter; // can overshoot above 1
  const squash = sc > 1 ? 1 + (sc - 1) * 0.4 : sc < 0 ? 0 : sc;
  return (
    <AbsoluteFill style={{ background: PAGE }}>
      <TechLabel name="Overshoot Spring" sub="High-bounce · squash on land" progress={labelIn} />
      <LogoCenter>
        <div style={{
          transform: `scale(${clamp(sc, 0, 2)}) scaleY(${squash < 0.5 ? 0.7 : 1})`,
          opacity: clamp(sc * 2, 0, 1),
          transformOrigin: '50% 100%',
        }}>
          <MusiniqueLogo />
        </div>
      </LogoCenter>
      <AccentRule opacity={clamp(enter * 2, 0, 1)} />
    </AbsoluteFill>
  );
};

// ── B03: Per-Path Stagger ─────────────────────────────────────────────────────
const B03_PerPathStagger: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const labelIn = spring({ frame, fps, config: { damping: 28, stiffness: 120, mass: 0.8 } });
  const STAGGER = 4;

  const pathFills = MUSINIQUE_PATHS.map((_, i) => INK);
  const pathOpacities = MUSINIQUE_PATHS.map((_, i) => {
    const s = spring({
      frame: frame - i * STAGGER - 10,
      fps,
      config: { damping: 22, stiffness: 200, mass: 0.7 },
    });
    return clamp(s, 0, 1);
  });
  const pathTransforms = MUSINIQUE_PATHS.map((_, i) => {
    const s = spring({
      frame: frame - i * STAGGER - 10,
      fps,
      config: { damping: 22, stiffness: 200, mass: 0.7 },
    });
    const sc = clamp(s, 0, 1);
    return `scale(${sc})`;
  });

  return (
    <AbsoluteFill style={{ background: PAGE }}>
      <TechLabel name="Per-Path Stagger" sub="47 paths · 4-frame offset cascade" progress={labelIn} />
      <LogoCenter>
        <MusiniqueLogo pathOpacities={pathOpacities} />
      </LogoCenter>
      <AccentRule />
    </AbsoluteFill>
  );
};

// ── B04: Draw-On Stroke ───────────────────────────────────────────────────────
const B04_DrawOnStroke: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const labelIn = spring({ frame, fps, config: { damping: 28, stiffness: 120, mass: 0.8 } });
  const DRAW_DUR = 100;
  const FILL_START = 110;
  const drawProgress = clamp(frame / DRAW_DUR, 0, 1);
  const fillProgress = iclamp(frame, [FILL_START, FILL_START + 40], [0, 1]);
  const estimatedLength = 12000;
  const dashOffset = estimatedLength * (1 - drawProgress);

  return (
    <AbsoluteFill style={{ background: PAGE }}>
      <TechLabel name="Draw-On Stroke" sub="evolvePath trace → fill flood" progress={labelIn} />
      <LogoCenter>
        <svg viewBox="0 0 1698.01 1832.98" width="85%" height="auto" style={{ display: 'block' }}>
          <g
            fill={`rgba(61,57,41,${fillProgress})`}
            stroke={SPARK}
            strokeWidth={4}
            strokeDasharray={estimatedLength}
            strokeDashoffset={dashOffset}
            style={{ paintOrder: 'stroke' }}
          >
            {MUSINIQUE_PATHS.map((d, i) => <path key={i} d={d} />)}
          </g>
        </svg>
      </LogoCenter>
      <AccentRule />
    </AbsoluteFill>
  );
};

// ── B05: Mask Reveal ──────────────────────────────────────────────────────────
const B05_MaskReveal: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps, durationInFrames } = useVideoConfig();
  const labelIn = spring({ frame, fps, config: { damping: 28, stiffness: 120, mass: 0.8 } });
  const MID = Math.floor(durationInFrames * 0.45);
  // Phase 1: left-to-right wipe
  const wipeR = iclamp(frame, [10, MID - 10], [0, 100]);
  // Phase 2: iris close from center
  const iris = iclamp(frame, [MID, durationInFrames - 20], [100, 0]);
  const isWipe = frame < MID;
  const clipPath = isWipe
    ? `inset(0 ${100 - wipeR}% 0 0)`
    : `inset(${(100 - iris) * 0.5}% ${(100 - iris) * 0.5}% ${(100 - iris) * 0.5}% ${(100 - iris) * 0.5}% round ${50}%)`;

  return (
    <AbsoluteFill style={{ background: PAGE }}>
      <TechLabel name="Mask Reveal" sub={isWipe ? 'Clip-path wipe →' : 'Iris close'} progress={labelIn} />
      <LogoCenter>
        <div style={{ clipPath, willChange: 'clip-path' }}>
          <MusiniqueLogo />
        </div>
      </LogoCenter>
      <AccentRule />
    </AbsoluteFill>
  );
};

// ── B06: Scale Zoom ───────────────────────────────────────────────────────────
const B06_ScaleZoom: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps, durationInFrames } = useVideoConfig();
  const labelIn = spring({ frame, fps, config: { damping: 28, stiffness: 120, mass: 0.8 } });
  const THIRD = Math.floor(durationInFrames / 2);
  // Phase 1: linear 8x→1x
  const linearScale = iclamp(frame, [10, THIRD], [8, 1]);
  // Phase 2: bezier 8x→1x (using spring as easing proxy)
  const bezierEnter = spring({ frame: frame - THIRD - 10, fps, config: { damping: 20, stiffness: 120 } });
  const bezierScale = iclamp(bezierEnter, [0, 1], [8, 1]);
  const scale = frame < THIRD ? linearScale : bezierScale;
  const label2 = frame < THIRD ? 'Linear push' : 'Bezier (spring)';

  return (
    <AbsoluteFill style={{ background: PAGE, overflow: 'hidden' }}>
      <TechLabel name="Scale Zoom" sub={label2} progress={labelIn} />
      <LogoCenter>
        <div style={{ transform: `scale(${scale})`, opacity: clamp(frame / 10, 0, 1) }}>
          <MusiniqueLogo />
        </div>
      </LogoCenter>
      <AccentRule />
    </AbsoluteFill>
  );
};

// ── B07: Rotation ─────────────────────────────────────────────────────────────
const B07_Rotation: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps, durationInFrames } = useVideoConfig();
  const labelIn = spring({ frame, fps, config: { damping: 28, stiffness: 120, mass: 0.8 } });
  const ENTER_DUR = 45;
  const enterRot = iclamp(frame, [0, ENTER_DUR], [-180, 0]);
  const enterScale = spring({ frame: frame - 8, fps, config: { damping: 22, stiffness: 160 } });
  const holdRot = frame > ENTER_DUR ? (frame - ENTER_DUR) * 0.4 : 0;
  const rot = frame < ENTER_DUR ? enterRot : holdRot;

  return (
    <AbsoluteFill style={{ background: PAGE }}>
      <TechLabel name="Rotation" sub="Pivot entrance · slow hold" progress={labelIn} />
      <LogoCenter>
        <div style={{
          transform: `rotate(${rot}deg) scale(${clamp(enterScale, 0.1, 1)})`,
          opacity: clamp(enterScale * 2, 0, 1),
        }}>
          <MusiniqueLogo />
        </div>
      </LogoCenter>
      <AccentRule />
    </AbsoluteFill>
  );
};

// ── B08: Skew And Shear ───────────────────────────────────────────────────────
const B08_SkewAndShear: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps, durationInFrames } = useVideoConfig();
  const labelIn = spring({ frame, fps, config: { damping: 28, stiffness: 120, mass: 0.8 } });
  const HALF = Math.floor(durationInFrames / 2);
  // lean in
  const skew = frame < HALF
    ? iclamp(frame, [10, HALF - 10], [0, -18])
    : iclamp(frame, [HALF, durationInFrames - 20], [-18, 0]);
  const enter = spring({ frame: frame - 5, fps, config: { damping: 22, stiffness: 160 } });

  return (
    <AbsoluteFill style={{ background: PAGE }}>
      <TechLabel name="Skew And Shear" sub="Italic lean · hold · release" progress={labelIn} />
      <LogoCenter>
        <div style={{
          transform: `skewX(${skew}deg) scale(${clamp(enter, 0, 1)})`,
          opacity: clamp(enter * 2, 0, 1),
        }}>
          <MusiniqueLogo />
        </div>
      </LogoCenter>
      <AccentRule />
    </AbsoluteFill>
  );
};

// ── B09: Opacity Through Blur ─────────────────────────────────────────────────
const B09_OpacityBlur: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const labelIn = spring({ frame, fps, config: { damping: 28, stiffness: 120, mass: 0.8 } });
  const FADE_DUR = 80;
  const blur = Math.max(0, interpolate(frame, [10, FADE_DUR], [24, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }));
  const opacity = iclamp(frame, [10, FADE_DUR], [0, 1]);

  return (
    <AbsoluteFill style={{ background: PAGE }}>
      <TechLabel name="Opacity Through Blur" sub="Materialise from soft focus" progress={labelIn} />
      <LogoCenter>
        <div style={{ filter: `blur(${blur}px)`, opacity }}>
          <MusiniqueLogo />
        </div>
      </LogoCenter>
      <AccentRule opacity={opacity} />
    </AbsoluteFill>
  );
};

// ── B10: Color Interpolation ──────────────────────────────────────────────────
// Treatment beat — palette violation labeled as such
const B10_ColorInterp: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const labelIn = spring({ frame, fps, config: { damping: 28, stiffness: 120, mass: 0.8 } });
  const STAGGER = 8;

  const hexToRgb = (hex: string) => [
    parseInt(hex.slice(1, 3), 16),
    parseInt(hex.slice(3, 5), 16),
    parseInt(hex.slice(5, 7), 16),
  ];
  const toHex = (rgb: number[]) => '#' + rgb.map(v => v.toString(16).padStart(2, '0')).join('');
  const lerp = (a: number[], b: number[], t: number) => a.map((v, i) => Math.round(v + (b[i] - v) * t));

  const inkRgb = hexToRgb(INK);
  const sparkRgb = hexToRgb(SPARK);

  const pathFills = MUSINIQUE_PATHS.map((_, i) => {
    const localFrame = frame - i * STAGGER;
    const t = Math.sin(Math.max(0, localFrame) * 0.035) * 0.5 + 0.5;
    return toHex(lerp(inkRgb, sparkRgb, t));
  });

  return (
    <AbsoluteFill style={{ background: PAGE }}>
      <TechLabel name="Color Interpolation" sub="Ink → terracotta → ink · treatment" progress={labelIn} />
      <LogoCenter>
        <MusiniqueLogo pathFills={pathFills} />
      </LogoCenter>
      <AccentRule />
    </AbsoluteFill>
  );
};

// ── B11: Kinetic Scatter ──────────────────────────────────────────────────────
const B11_KineticScatter: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps, durationInFrames } = useVideoConfig();
  const labelIn = spring({ frame, fps, config: { damping: 28, stiffness: 120, mass: 0.8 } });
  const EXPLODE = 30;
  const HOLD = EXPLODE + 30;
  const SNAP_START = HOLD;

  // Phase 1: explode outward (0-30)
  // Phase 2: hold scattered (30-60)
  // Phase 3: spring back (60+)
  const snapBack = spring({ frame: frame - SNAP_START, fps, config: { damping: 16, stiffness: 240, mass: 0.8 } });
  const explodeProgress = clamp(frame / EXPLODE, 0, 1);
  const phase = frame < EXPLODE ? 'explode' : frame < HOLD ? 'hold' : 'snap';

  const pathTransforms = MUSINIQUE_PATHS.map((_, i) => {
    const angle = (i / 47) * Math.PI * 2;
    const dist = 600 + seed(i, 97) * 400;
    const ex = Math.cos(angle) * dist;
    const ey = Math.sin(angle) * dist;

    let tx = 0, ty = 0;
    if (phase === 'explode') {
      tx = ex * explodeProgress;
      ty = ey * explodeProgress;
    } else if (phase === 'hold') {
      tx = ex;
      ty = ey;
    } else {
      tx = ex * (1 - clamp(snapBack, 0, 1));
      ty = ey * (1 - clamp(snapBack, 0, 1));
    }
    // Convert from CSS px offsets in the SVG coordinate space
    return `translate(${tx}, ${ty})`;
  });

  return (
    <AbsoluteFill style={{ background: PAGE }}>
      <TechLabel name="Kinetic Scatter" sub="Explode outward · spring back" progress={labelIn} />
      <LogoCenter>
        <MusiniqueLogo pathTransforms={pathTransforms} />
      </LogoCenter>
      <AccentRule />
    </AbsoluteFill>
  );
};

// ── B12: Glitch Slices ────────────────────────────────────────────────────────
const B12_GlitchSlices: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const labelIn = spring({ frame, fps, config: { damping: 28, stiffness: 120, mass: 0.8 } });
  const GLITCH_START = 20;
  const GLITCH_DUR = 40;
  const SNAP = GLITCH_START + GLITCH_DUR;
  const glitchProgress = iclamp(frame, [GLITCH_START, SNAP], [1, 0]);
  const SLICES = 6;
  const sliceOffsets = Array.from({ length: SLICES }, (_, i) => {
    const dir = i % 2 === 0 ? 1 : -1;
    return dir * seed(i, 113) * 60 * glitchProgress;
  });
  const enter = spring({ frame: frame - 5, fps, config: { damping: 22, stiffness: 160 } });

  return (
    <AbsoluteFill style={{ background: PAGE, overflow: 'hidden' }}>
      <TechLabel name="Glitch Slices" sub="8-frame offset · snap clean" progress={labelIn} />
      <LogoCenter style={{ position: 'relative' }}>
        <div style={{ position: 'relative', width: '85%', aspectRatio: '1698/1832', opacity: clamp(enter * 2, 0, 1) }}>
          {sliceOffsets.map((offset, si) => (
            <div key={si} style={{
              position: 'absolute',
              top: `${(si / SLICES) * 100}%`,
              height: `${100 / SLICES}%`,
              left: 0, right: 0,
              overflow: 'hidden',
              transform: `translateX(${offset}px)`,
            }}>
              <div style={{
                position: 'absolute',
                top: `-${(si / SLICES) * 100}%`,
                height: `${SLICES * 100}%`,
                left: 0, right: 0,
                display: 'flex', alignItems: 'center', justifyContent: 'center',
              }}>
                <svg viewBox="0 0 1698.01 1832.98" width="100%" style={{ display: 'block' }}>
                  {MUSINIQUE_PATHS.map((d, i) => <path key={i} d={d} fill={INK} />)}
                </svg>
              </div>
            </div>
          ))}
        </div>
      </LogoCenter>
      <AccentRule />
    </AbsoluteFill>
  );
};

// ── B13: Trail Echo ───────────────────────────────────────────────────────────
const B13_TrailEcho: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps, durationInFrames } = useVideoConfig();
  const labelIn = spring({ frame, fps, config: { damping: 28, stiffness: 120, mass: 0.8 } });
  const TRAILS = 5;
  const SLIDE_SPEED = 8; // px per frame
  const SLIDE_DUR = Math.floor(durationInFrames * 0.55);
  const SETTLE_START = SLIDE_DUR;

  const settleSpring = spring({ frame: frame - SETTLE_START, fps, config: { damping: 18, stiffness: 200 } });
  const mainX = frame < SETTLE_START
    ? iclamp(frame, [0, SLIDE_DUR], [-600, 0])
    : 0;

  return (
    <AbsoluteFill style={{ background: PAGE, overflow: 'hidden' }}>
      <TechLabel name="Trail Echo" sub="Ghost copies · fast slide · settle" progress={labelIn} />
      <LogoCenter>
        {/* Trail copies */}
        {Array.from({ length: TRAILS }, (_, ti) => {
          const lag = (ti + 1) * 18;
          const trailX = frame < SLIDE_DUR
            ? iclamp(frame - lag, [0, SLIDE_DUR], [-600, 0])
            : 0;
          return (
            <div key={ti} style={{
              position: 'absolute',
              transform: `translateX(${trailX}px)`,
              opacity: (TRAILS - ti) / (TRAILS * 4),
              pointerEvents: 'none',
            }}>
              <MusiniqueLogo />
            </div>
          );
        })}
        {/* Main logo */}
        <div style={{ transform: `translateX(${mainX}px)` }}>
          <MusiniqueLogo />
        </div>
      </LogoCenter>
      <AccentRule />
    </AbsoluteFill>
  );
};

// ── B14: Noise Wobble ─────────────────────────────────────────────────────────
const B14_NoiseWobble: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps, durationInFrames } = useVideoConfig();
  const labelIn = spring({ frame, fps, config: { damping: 28, stiffness: 120, mass: 0.8 } });
  const SETTLE_START = Math.floor(durationInFrames * 0.55);
  const settle = spring({ frame: frame - SETTLE_START, fps, config: { damping: 20, stiffness: 180 } });
  const wobbleAmt = frame < SETTLE_START ? 1 : clamp(1 - settle, 0, 1);
  const enter = spring({ frame: frame - 5, fps, config: { damping: 22, stiffness: 160 } });

  const pathTransforms = MUSINIQUE_PATHS.map((_, i) => {
    const nx = Math.sin(frame * 0.18 + i * 0.8) * 8 * wobbleAmt;
    const ny = Math.cos(frame * 0.15 + i * 1.1) * 8 * wobbleAmt;
    return `translate(${nx}, ${ny})`;
  });

  return (
    <AbsoluteFill style={{ background: PAGE }}>
      <TechLabel name="Noise Wobble" sub="Micro-jitter · settles to still" progress={labelIn} />
      <LogoCenter>
        <div style={{ opacity: clamp(enter * 2, 0, 1) }}>
          <MusiniqueLogo pathTransforms={pathTransforms} />
        </div>
      </LogoCenter>
      <AccentRule />
    </AbsoluteFill>
  );
};

// ── B15: Elastic Physics ──────────────────────────────────────────────────────
const B15_ElasticPhysics: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const labelIn = spring({ frame, fps, config: { damping: 28, stiffness: 120, mass: 0.8 } });
  const elastic = spring({ frame: frame - 20, fps, config: { damping: 5, stiffness: 180, mass: 1.2 } });
  const ty = (1 - clamp(elastic, 0, 2)) * -400;
  const scaleY = 0.7 + clamp(elastic, 0, 1) * 0.3;
  const scaleX = 2 - scaleY;

  return (
    <AbsoluteFill style={{ background: PAGE }}>
      <TechLabel name="Elastic Physics" sub="Drop · squash · rebound" progress={labelIn} />
      <LogoCenter>
        <div style={{
          transform: `translateY(${ty}px) scaleY(${scaleY}) scaleX(${scaleX})`,
          transformOrigin: '50% 100%',
          opacity: clamp(elastic * 3, 0, 1),
        }}>
          <MusiniqueLogo />
        </div>
      </LogoCenter>
      <AccentRule />
    </AbsoluteFill>
  );
};

// ── B16: Path Cascade ─────────────────────────────────────────────────────────
const B16_PathCascade: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const labelIn = spring({ frame, fps, config: { damping: 28, stiffness: 120, mass: 0.8 } });
  const STAGGER = 5;

  const pathOpacities = MUSINIQUE_PATHS.map((_, i) => {
    const s = spring({ frame: frame - i * STAGGER - 10, fps, config: { damping: 22, stiffness: 200 } });
    return clamp(s, 0, 1);
  });

  const pathTransforms = MUSINIQUE_PATHS.map((_, i) => {
    const s = spring({ frame: frame - i * STAGGER - 10, fps, config: { damping: 22, stiffness: 200 } });
    const sc = clamp(s, 0, 1);
    const rain = (1 - sc) * -800; // rain from above (negative Y = above)
    return `translate(0, ${rain})`;
  });

  return (
    <AbsoluteFill style={{ background: PAGE, overflow: 'hidden' }}>
      <TechLabel name="Path Cascade" sub="47 paths rain from above" progress={labelIn} />
      <LogoCenter>
        <MusiniqueLogo pathOpacities={pathOpacities} pathTransforms={pathTransforms} />
      </LogoCenter>
      <AccentRule />
    </AbsoluteFill>
  );
};

// ── B17: Card Flip ────────────────────────────────────────────────────────────
const B17_CardFlip: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps, durationInFrames } = useVideoConfig();
  const labelIn = spring({ frame, fps, config: { damping: 28, stiffness: 120, mass: 0.8 } });
  const FLIP_DUR = 50;
  const FLIP_START = 20;
  const rotY = iclamp(frame, [FLIP_START, FLIP_START + FLIP_DUR], [0, 180]);
  const enter = spring({ frame: frame - 8, fps, config: { damping: 22, stiffness: 160 } });
  // Show back face (inverted/terracotta) when past 90deg
  const isFront = rotY < 90;

  return (
    <AbsoluteFill style={{ background: PAGE, perspective: 1200 }}>
      <TechLabel name="Card Flip" sub="rotateY · mark on both faces" progress={labelIn} />
      <LogoCenter>
        <div style={{
          transform: `rotateY(${rotY}deg) scale(${clamp(enter, 0.1, 1)})`,
          opacity: clamp(enter * 2, 0, 1),
          transformStyle: 'preserve-3d',
        }}>
          <MusiniqueLogo fill={isFront ? INK : SPARK} />
        </div>
      </LogoCenter>
      <AccentRule />
    </AbsoluteFill>
  );
};

// ── B18: Shadow Play ──────────────────────────────────────────────────────────
const B18_ShadowPlay: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps, durationInFrames } = useVideoConfig();
  const labelIn = spring({ frame, fps, config: { damping: 28, stiffness: 120, mass: 0.8 } });
  const HALF = Math.floor(durationInFrames * 0.5);
  const shadowSpring = spring({ frame: frame - 10, fps, config: { damping: 12, stiffness: 140 } });
  const shadowRestore = spring({ frame: frame - HALF, fps, config: { damping: 18, stiffness: 200 } });
  const enter = spring({ frame: frame - 5, fps, config: { damping: 22, stiffness: 160 } });

  const shadowOffX = frame < HALF
    ? clamp(shadowSpring, 0, 1) * 60 - 60  // grows to +60
    : (1 - clamp(shadowRestore, 0, 1)) * 60; // springs back
  const shadowOffY = frame < HALF
    ? clamp(shadowSpring, 0, 1) * 60 - 60
    : (1 - clamp(shadowRestore, 0, 1)) * 60;
  const shadowBlur = 20 + Math.abs(shadowOffX) * 0.3;

  return (
    <AbsoluteFill style={{ background: PAGE }}>
      <TechLabel name="Shadow Play" sub="Shadow animates · then rejoins" progress={labelIn} />
      <LogoCenter>
        <div style={{
          position: 'relative',
          opacity: clamp(enter * 2, 0, 1),
          transform: `scale(${clamp(enter, 0.1, 1)})`,
        }}>
          {/* Shadow layer */}
          <div style={{
            position: 'absolute',
            top: 0, left: 0, right: 0, bottom: 0,
            transform: `translate(${shadowOffX}px, ${shadowOffY}px)`,
          }}>
            <MusiniqueLogo fill={INK} opacity={0.25} style={{ filter: `blur(${shadowBlur / 10}px)` }} />
          </div>
          {/* Main layer */}
          <MusiniqueLogo />
        </div>
      </LogoCenter>
      <AccentRule />
    </AbsoluteFill>
  );
};

// ── B19: Composer Summon ──────────────────────────────────────────────────────
const B19_ComposerSummon: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const labelIn = spring({ frame, fps, config: { damping: 28, stiffness: 120, mass: 0.8 } });
  const SEND_FRAME = 40;
  const SUMMON_START = SEND_FRAME + 20;

  // Spark flash on send
  const sparkFlash = frame >= SEND_FRAME && frame < SEND_FRAME + 12
    ? iclamp(frame, [SEND_FRAME, SEND_FRAME + 12], [1, 0])
    : 0;

  // Logo materializes after summon
  const summon = spring({ frame: frame - SUMMON_START, fps, config: { damping: 18, stiffness: 180 } });
  const logoOpacity = clamp(summon, 0, 1);
  const logoScale = 0.7 + clamp(summon, 0, 1) * 0.3;

  // "Send" button pulse
  const sendPulse = iclamp(frame, [SEND_FRAME - 5, SEND_FRAME + 5], [0.8, 1.4]);

  return (
    <AbsoluteFill style={{ background: PAGE }}>
      <TechLabel name="Composer Summon" sub="Sent from Claude · spark on send" progress={labelIn} />

      {/* Terracotta spark burst */}
      {sparkFlash > 0 && (
        <div style={{
          position: 'absolute', top: '30%', left: '50%',
          transform: 'translate(-50%, -50%)',
          width: 200 * (2 - sparkFlash), height: 200 * (2 - sparkFlash),
          borderRadius: '50%',
          background: `radial-gradient(circle, ${SPARK} 0%, transparent 70%)`,
          opacity: sparkFlash,
          pointerEvents: 'none',
        }} />
      )}

      {/* Send button indicator */}
      {frame < SUMMON_START && (
        <div style={{
          position: 'absolute', bottom: '28%', left: '50%',
          transform: `translate(-50%, 0) scale(${sendPulse})`,
          background: SPARK, borderRadius: 28,
          padding: '14px 36px',
          fontFamily: SANS, fontSize: 20, fontWeight: 700, color: '#FFF',
          letterSpacing: 1,
          opacity: clamp(frame / 15, 0, 1),
        }}>→ SEND</div>
      )}

      {/* Logo materializing */}
      <LogoCenter>
        <div style={{
          transform: `scale(${logoScale})`,
          opacity: logoOpacity,
        }}>
          <MusiniqueLogo />
        </div>
      </LogoCenter>
      <AccentRule />
    </AbsoluteFill>
  );
};

// ── B20: Exit Family ──────────────────────────────────────────────────────────
const B20_ExitFamily: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps, durationInFrames } = useVideoConfig();
  const labelIn = spring({ frame, fps, config: { damping: 28, stiffness: 120, mass: 0.8 } });
  const THIRD = Math.floor(durationInFrames / 3);
  const phase = frame < THIRD ? 0 : frame < THIRD * 2 ? 1 : 2;
  const localFrame = frame - phase * THIRD;

  // Exit 0: shrink-spin
  const shrinkSpin = (
    <div style={{
      transform: `scale(${Math.max(0, 1 - localFrame / 40)}) rotate(${localFrame * 8}deg)`,
      opacity: Math.max(0, 1 - localFrame / 35),
    }}>
      <MusiniqueLogo />
    </div>
  );

  // Exit 1: blur-out
  const blurOut = (
    <div style={{
      filter: `blur(${Math.min(24, localFrame * 0.5)})`,
      opacity: Math.max(0, 1 - localFrame / 35),
    }}>
      <MusiniqueLogo />
    </div>
  );

  // Exit 2: mask-close
  const maskClose = (
    <div style={{
      clipPath: `inset(0 ${clamp(localFrame / 40, 0, 1) * 100}% 0 0)`,
    }}>
      <MusiniqueLogo />
    </div>
  );

  const phaseLabel = phase === 0 ? 'Exit 1 · Shrink Spin' : phase === 1 ? 'Exit 2 · Blur Out' : 'Exit 3 · Mask Close';

  return (
    <AbsoluteFill style={{ background: PAGE }}>
      <TechLabel name="Exit Family" sub={phaseLabel} progress={labelIn} />
      <LogoCenter>
        {phase === 0 ? shrinkSpin : phase === 1 ? blurOut : maskClose}
      </LogoCenter>
      <AccentRule />
    </AbsoluteFill>
  );
};

