// TIMING ACCUMULATOR + MAIN COMPOSITION
// ═══════════════════════════════════════════════════════════════════════════════

const TIMED = TIMING.map(t => ({ ...t }));
export const TOTAL_FRAMES = TIMED.reduce((a, b) => a + b.frames, 0);

export const MusiniquLogoRemotionShowcase: React.FC = () => {
  let at = 0;

  const seqs = TIMED.map((t) => {
    const from = at;
    at += t.frames;

    let content: React.ReactNode = null;

    switch (t.id) {

      case 'B00':
        content = (
          <ClaudeComposerAsk {...claudeComposerAskSchema.parse({
            greeting: 'Ciao, Liam',
            topic: TOPIC,
            segment: SEGMENT,
            command: 'animate musinique-logo.svg — 47 paths — every Remotion technique — for review',
            runningText: 'loading technique showcase…',
            folderLabel: FOLDER,
            output: [
              '47 paths extracted',
              'viewBox 0 0 1698.01 1832.98 — near-square',
              '20 techniques queued',
              'Kokoro am_onyx narration locked',
            ],
          })} />
        );
        break;

      case 'B01': content = <B01_SpringEntrance />; break;
      case 'B02': content = <B02_OvershootSpring />; break;
      case 'B03': content = <B03_PerPathStagger />; break;
      case 'B04': content = <B04_DrawOnStroke />; break;
      case 'B05': content = <B05_MaskReveal />; break;
      case 'B06': content = <B06_ScaleZoom />; break;
      case 'B07': content = <B07_Rotation />; break;
      case 'B08': content = <B08_SkewAndShear />; break;
      case 'B09': content = <B09_OpacityBlur />; break;
      case 'B10': content = <B10_ColorInterp />; break;
      case 'B11': content = <B11_KineticScatter />; break;
      case 'B12': content = <B12_GlitchSlices />; break;
      case 'B13': content = <B13_TrailEcho />; break;
      case 'B14': content = <B14_NoiseWobble />; break;
      case 'B15': content = <B15_ElasticPhysics />; break;
      case 'B16': content = <B16_PathCascade />; break;
      case 'B17': content = <B17_CardFlip />; break;
      case 'B18': content = <B18_ShadowPlay />; break;
      case 'B19': content = <B19_ComposerSummon />; break;
      case 'B20': content = <B20_ExitFamily />; break;

      case 'B21':
        content = (
          <ClaudeComposerAsk {...claudeComposerAskSchema.parse({
            greeting: 'Your turn.',
            topic: TOPIC,
            segment: SEGMENT,
            command: 'Animate my SVG logo with these techniques: Per-Path Stagger, Kinetic Scatter, Draw-On Stroke, Elastic Physics, Mask Reveal. Build each as a Remotion scene at 1080x1920, 30fps, cream #FAF9F5 background, ink #3D3929 fill, terracotta #D97757 accent. Export separate mp4s for review.',
            runningText: 'paste this into Claude…',
            folderLabel: FOLDER,
          })} />
        );
        break;

      case 'B22':
        content = (
          <ClaudeTitleOutro {...claudeTitleOutroSchema.parse({
            title: 'One Logo, 47 Paths, Every Move Remotion Knows.',
            handle: '@NikBearBrown',
            subline: 'Liam, in for Bear.',
          })} />
        );
        break;

      default:
        content = (
          <AbsoluteFill style={{ background: PAGE, alignItems: 'center', justifyContent: 'center' }}>
            <div style={{ fontFamily: SERIF, fontSize: 48, color: INK }}>{t.id}</div>
          </AbsoluteFill>
        );
    }

    return (
      <Sequence key={t.id} from={from} durationInFrames={t.frames} name={t.id}>
        {content}
        {t.audio && (
          <Audio src={staticFile(t.audio)} />
        )}
      </Sequence>
    );
  });

  return <AbsoluteFill>{seqs}</AbsoluteFill>;
};
